#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;
using vi = vector<int>;
using vvi = vector<vector<int>>;
using ld = long double;

const int MOD = 1000000007;

struct mod_int {
    int val;
    mod_int(long long v = 0) {
        v %= MOD;
        if (v < 0) v += MOD;
        val = v;
    }
    explicit operator int() const { return val; }
    mod_int& operator+=(const mod_int &o) { val = (val + o.val) % MOD; return *this; }
    mod_int& operator-=(const mod_int &o) { val = (val - o.val + MOD) % MOD; return *this; }
    mod_int& operator*=(const mod_int &o) { val = (ll)val * o.val % MOD; return *this; }
    mod_int& operator/=(const mod_int &o) { return *this *= o.inv(); }
    mod_int operator-() const { return val ? MOD - val : 0; }
    bool operator==(const mod_int &o) const { return val == o.val; }
    bool operator!=(const mod_int &o) const { return val != o.val; }
    mod_int inv() const {
        int a = val, b = MOD, x = 0, y = 1;
        while (a > 1) {
            int q = a / b;
            a %= b; swap(a, b);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + MOD : x;
    }
    mod_int pow(ll p) const {
        mod_int res(1), a(*this);
        while (p) {
            if (p & 1) res *= a;
            a *= a;
            p >>= 1;
        }
        return res;
    }
    friend mod_int operator+(mod_int a, const mod_int &b) { return a += b; }
    friend mod_int operator-(mod_int a, const mod_int &b) { return a -= b; }
    friend mod_int operator*(mod_int a, const mod_int &b) { return a *= b; }
    friend mod_int operator/(mod_int a, const mod_int &b) { return a /= b; }
};

const int N_MAX = 10;
int N;
mod_int prob[N_MAX][N_MAX];

int main() {
    ios_base::sync_with_stdio(false); cin.tie(nullptr);
    cin >> N;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            int p; cin >> p;
            prob[i][j] = mod_int(p) / mod_int(100);
        }

    vvi masks_with_count(N + 1);
    vi lookup(1 << N, -1);
    for (int mask = 0; mask < 1 << N; mask++) {
        int cnt = __builtin_popcount(mask);
        lookup[mask] = masks_with_count[cnt].size();
        masks_with_count[cnt].push_back(mask);
    }

    using Map = unordered_map<ll, mod_int>;
    Map possible_masks;
    possible_masks[1LL << lookup[0]] = mod_int(1);

    for (int left = 0; left < N; left++) {
        Map new_possible_masks;
        vector<mod_int> products(1 << N, mod_int(1));

        for (int cur = 0; cur < 1 << N; cur++) {
            mod_int prod(1);
            for (int r = 0; r < N; r++) {
                if (cur >> r & 1) prod *= prob[left][r];
                else prod += mod_int(1) - prob[left][r] - mod_int(1);
            }
            products[cur] = prod;
        }

        vector<ll> new_bits(N, 0);
        vector<ll> new_possible(1 << N, 0);

        for (auto &[mask_key, p_val] : possible_masks) {
            ll possible = mask_key;
            mod_int prob_cur = p_val;

            fill(new_bits.begin(), new_bits.end(), 0);
            for (int mask : masks_with_count[left]) {
                if (possible >> lookup[mask] & 1) {
                    for (int i = 0; i < N; i++) {
                        if ((mask >> i & 1) == 0) {
                            new_bits[i] |= 1LL << lookup[mask | (1 << i)];
                        }
                    }
                }
            }

            new_possible[0] = 0;
            for (int cur = 1; cur < 1 << N; cur++) {
                new_possible[cur] = new_possible[cur & (cur - 1)] | new_bits[__builtin_ctz(cur)];
                new_possible_masks[new_possible[cur]] += prob_cur * products[cur];
            }
        }

        possible_masks.swap(new_possible_masks);
        cerr << possible_masks.size() << '\n';
    }

    mod_int ans(0);
    ll full_mask = (1 << N) - 1;
    for (auto &[mask_key, p_val] : possible_masks) {
        if (mask_key >> lookup[full_mask] & 1) {
            ans += p_val;
        }
    }
    cout << (int)ans << '\n';
}
